import React from 'react';
import { Link } from 'react-router-dom';
import './Page.css';

const About = () => {
  return (
    <main className="page">
      <div className="page-inner">
        <header className="page-hero">
          <h1>About Ravindra Stores</h1>
          <p className="muted">Family-run, fresh produce and a community-first approach.</p>
        </header>

        <section className="page-card">
          <p>
            Ravindra Stores is a family-run grocery business dedicated to delivering fresh,
            high-quality groceries to our community. We source products from trusted
            suppliers and focus on sustainable, local produce where possible.
          </p>

          <h3 style={{ marginTop: '1rem' }}>Our Mission</h3>
          <p className="muted">To make healthy, affordable food accessible to everyone — with fast delivery and friendly service.</p>

          <h3 style={{ marginTop: '1rem' }}>Get in touch</h3>
          <p className="muted">Have questions? Visit our <Link to="/contact">Contact</Link> page.</p>
        </section>
      </div>
    </main>
  );
};

export default About;
